from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from pathlib import Path
out=Path('docs'); d=Document(); sec=d.sections[0]
sec.top_margin=sec.bottom_margin=Inches(.7)
sec.left_margin=sec.right_margin=Inches(.8)
for name in ['Normal','Title','Heading 1','Heading 2']:
 s=d.styles[name]; s.font.name='Calibri'; s.font.color.rgb=RGBColor(0,0,0)
d.styles['Normal'].font.size=Pt(11)
d.styles['Normal'].paragraph_format.space_after=Pt(7)
d.styles['Title'].font.size=Pt(28)
d.styles['Heading 1'].font.size=Pt(19)
d.styles['Heading 2'].font.size=Pt(13)
def p(t): d.add_paragraph(t)
def h(t): d.add_heading(t,2)
def bullets(items):
 for t in items: d.add_paragraph(t,'List Bullet')
def page(title): d.add_page_break(); d.add_heading(title,1)
d.add_paragraph('ANU Learning Hub Project Overview','Title')
p('Functional and technical overview | 27 October 2026')
p('ANU Learning Hub is a learning management platform for structured medical and ultrasound training. It connects course content, trainees, instructors, batch administration, assessments, volume resources, and VR learning activity in one role based workspace.')
p('This document explains the project purpose, the responsibilities of its four user roles, the main modules, and the flow from content preparation to learner progress review.')
h('Project objectives')
bullets(['Organize training into certifications, courses, chapters, modules, and learning resources.','Assign learning to batches and individual trainees and make learning dates visible.','Support practice, image interpretation, assessments, challenges, and review of available results.','Manage training volumes and related recordings, with approval and conversion tracking.','Control institution content access and support live observation of trainee VR activity.'])
h('Application architecture')
p('React web interface → Express API → PostgreSQL and Supabase services. Storage and media integrations support training assets, volume processing, and live streaming. VR clients also use authenticated server APIs for learning and streaming sessions.')
bullets(['Presentation layer: React 18, React Router, Tailwind CSS, Material UI, calendars, and charts.','Application layer: Node.js and Express with routes, controllers, models, and services.','Data and integrations: PostgreSQL, Supabase, AWS S3 and Batch integrations, Amazon IVS, and Socket.IO.','Identity: JWT based sessions, account verification, and role specific application views.'])
page('User roles and responsibilities')
h('Super Admin')
p('Role 99 provides central content and access administration. Its navigation includes Dashboard, Curriculum, Certifications, Volumes, Cluster, Course Mapping, Reattempts, Academics, SVT Course, and Content Access.')
p('Content Access supports course management, institution visibility, batch and individual assignments, institution administrator creation, Super Admin accounts, and migration review for legacy content ownership.')
h('Admin')
p('Role 101 supports institution training operations through Dashboard, Batch, Instructors, Trainees, Schedules, Certifications, Streams, Volumes, Cluster, and SVT Course.')
p('The Admin organizes batches and members, maintains user profiles, configures targeted learning, reviews progress, manages available content, and uses the streaming workspace to observe trainee activity.')
h('Instructor')
p('Role 102 supports teaching and learner review through Dashboard, Batch, Trainees, Certifications, Volumes, and Cluster. Instructors inspect available batch details and trainee progress, browse learning content, and work with volume resources and recordings.')
h('Trainee')
p('Role 103 is labelled Learner in the interface. Its navigation includes Dashboard, My Learning, Schedules, Queries, Batch, Streams, and Assigned Courses.')
p('The trainee studies assigned content, performs available learning activities, submits assessments, checks attempts and feedback, views learning dates and batch information, and raises queries.')
h('Additional course assignment access')
p('The Content Access route also supports Admin and Instructor editors, although their current sidebar does not display that entry. Route support and menu visibility should be treated as distinct parts of the interface.')
page('Main project modules')
modules=[('Dashboard and progress','Provides role specific summaries of learning, batches, learners, and progress. Trainee views focus on personal activity; administrative and instructor views support oversight.'),('People and batches','Maintains trainees, instructors, profiles, batch membership, and batch details. Targeted learning links selected content and dates to training groups.'),('Curriculum and certifications','Organizes the learning structure and provides navigation from certification and course content into chapters, modules, and resources. Course Mapping and SVT Course support additional content configuration.'),('Learning and assessment','My Learning exposes resources, practice, image interpretation, tests, and challenges when available for the selected unit. Results can include attempt history, feedback, visualization, and submitted content.'),('Volumes and clusters','Supports volume uploads, metadata management, approval and conversion status, related recordings, and downloads. Clusters organize selected volumes into groups.'),('Schedules and queries','Schedules present targeted learning dates in a calendar. Queries provide a place for trainees to raise questions and view query records.'),('Content access and institutions','Controls course lifecycle and availability across institutions, batches, and individual trainees. Super Admin tools also handle administrators and legacy ownership review.'),('VR streaming','A trainee VR client publishes video and microphone through Amazon IVS Real-Time. The trainee can receive a self preview, while institution administrators view replicated streams in the scan center workspace.')]
for title,body in modules: h(title);p(body)
page('Role flows and training lifecycle')
h('Super Admin flow')
p('Login → Dashboard → Prepare curriculum and certifications → Configure mappings and resources → Manage institution access and course state → Distribute content → Review learning data and reattempts.')
h('Admin flow')
p('Login → Dashboard → Create or update users and batches → Configure targeted learning → Check schedules → Monitor trainee progress and streams. Volumes, clusters, certifications, and custom course content are available as separate working modules.')
h('Instructor flow')
p('Login → Dashboard → Open batch or trainee → Review learning progress. Select Certifications to inspect content, or Volumes and Cluster to organize training resources and review available recordings.')
h('Trainee flow')
p('Login → Dashboard → My Learning or Assigned Courses → Select certification and learning unit → Study resources or perform an available activity → Submit work → Review attempts and available feedback. Schedules, Queries, Batch, and Streams are separate navigation branches.')
h('End to end lifecycle')
bullets(['Prepare: configure curriculum, course structure, learning resources, and volume content.','Distribute: set course availability and assign learning through batches or individual access.','Learn: trainees study resources and perform the activities available in their learning units.','Review: instructors and administrators inspect learner progress, activity results, and available recordings.','Maintain: update content, manage access, and review reattempt data and outstanding content approvals.'])
h('Project structure')
p('client/src contains the web interface, role menus, pages, and API clients. server/v1 contains the main Express application, authentication, API routes, controllers, models, services, migrations, and tests. Streaming and multi tenant rollout notes are maintained with the server.')
h('Implementation reference')
p('Reference areas: client/src/components/sideBar.js; client/src/routes/route.js; client/src/pages; client/package.json; server/v1/app.js; server/v1/package.json; server/v1/STREAMING.md; server/v1/MULTI_TENANT_ROLLOUT.md.')
d.save(out/'ANU_Project_Overview.docx')
print((out/'ANU_Project_Overview.docx').resolve())
